/* ===================== BÀI 32 · Lab nhiều nguồn sự kiện ===================== */
/* Bài 32 · Lab nhiều nguồn sự kiện (AMTS-EMB-001-M08-L04, MC51-032) — sinh bởi tools/author/mcu8051/l32.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR32=[{"label":"Ví dụ: Thay hỏi vòng bằng ngắt INT0","code":"; Ví dụ 1: thay hỏi vòng bằng ngắt INT0 kích sườn\n; Cùng công việc, cùng hai lần bấm như ví dụ 2. Sườn xuống\n; bật IE0 bất kể main đang làm gì; ISR đếm.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H                   ; vectơ INT0\n        INC     30H                     ; 1 lệnh, không đổi cờ: không cất\n        RETI\n        ORG     0030H\nMAIN:   MOV     30H,#0\n        SETB    IT0                     ; kích sườn\n        MOV     IE,#81H                 ; EA + EX0\n        MOV     R6,#4\nVONG:   MOV     R7,#50                  ; công việc như ví dụ 2\n        DJNZ    R7,$\n        DJNZ    R6,VONG\n        CLR     EA\n        SJMP    $\n        END\n","note":"Cùng công việc, cùng kịch bản bấm: ISR INT0 được gọi ở chu kỳ 43 và 203, vài chu kỳ sau mỗi lần bấm, bất kể main đang ở đâu. 30H = 02H; 431 chu kỳ.","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Lỗi: Hỏi vòng chân bỏ lỡ lần bấm ngắn","code":"; Ví dụ 2 (LỖI): hỏi vòng chân K1 giữa các khối công việc\n; K1 nối P3.2 (bấm = 0). Main xét chân một lần rồi làm\n; \"công việc\" 100 chu kỳ: lần bấm ngắn lọt vào khe bị bỏ lỡ.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0030H\nMAIN:   MOV     30H,#0                  ; số lần bấm đếm được\n        MOV     R6,#4                   ; 4 vòng làm việc\nVONG:   JB      P3.2,KHONG              ; hỏi vòng: chân = 1 → không bấm\n        INC     30H\nNHA:    JNB     P3.2,NHA                ; chờ nhả nút\nKHONG:  MOV     R7,#50                  ; công việc: 50 × 2 chu kỳ\n        DJNZ    R7,$\n        DJNZ    R6,VONG\n        SJMP    $\n        END\n","note":"Main xét chân P3.2 ở chu kỳ 5, 110, 215, 365 rồi bận 100 chu kỳ. Kịch bản: K1 bấm ở 40–80 (lọt vào khe, bị bỏ lỡ) và 200–260 (thấy ở lần xét 215, trễ 15 chu kỳ). Kết quả 30H = 01H cho 2 lần bấm; 470 chu kỳ.","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Ví dụ: Hai nguồn cùng mức, tick bị trễ","code":"; Ví dụ 3: hai nguồn cùng mức ưu tiên — tick bị trễ\n; Tick Timer 0 mỗi 40 chu kỳ (ISR ghi TL0 vào 40H.. như ví\n; dụ 3). K1 (INT0) gọi ISR \"xử lý\" dài 33 chu kỳ. Tick rơi\n; vào lúc ISR INT0 đang chạy phải chờ nó xong.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H                   ; INT0: xử lý sự kiện K1\n        LJMP    X0ISR\n        ORG     000BH                   ; Timer 0: tick, tự đo độ trễ\n        MOV     @R0,TL0\n        INC     R0\n        RETI\n        ORG     0030H\nMAIN:   MOV     R0,#40H\n        MOV     30H,#0                  ; số lần xử lý K1\n        MOV     TMOD,#02H\n        MOV     TH0,#0D8H               ; tick 40 chu kỳ\n        MOV     TL0,#0D8H\n        SETB    IT0\n        MOV     IE,#83H                 ; EA + ET0 + EX0, IP = 0\n        SETB    TR0\n        MOV     R6,#100                 ; chờ 200 chu kỳ\n        DJNZ    R6,$\n        CLR     TR0\n        CLR     EA\n        SJMP    $\nX0ISR:  MOV     31H,#12                 ; công việc: 12 × 2 chu kỳ\n        DJNZ    31H,$\n        INC     30H\n        RETI\n        END\n","note":"K1 bấm ở chu kỳ 50 (kịch bản), ngay trước lần tràn 55. ISR INT0 cùng mức chạy tới 85 nên tick chờ: ô 40H = FBH = độ trễ 34 chu kỳ. Các tick sau 3–4. Đoán trước: nếu bấm K1 ngay sau một lần tràn thì 40H bằng bao nhiêu?","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Lỗi: ISR dài hơn hai tick, mất tick","code":"; Ví dụ 4 (LỖI): ISR dài hơn hai chu kỳ tick — mất tick\n; Như ví dụ 3 nhưng ISR INT0 dài khoảng 100 chu kỳ. TF0 bật\n; hai lần trong lúc đó: cờ chỉ là một bit, một tick mất.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H\n        LJMP    X0ISR\n        ORG     000BH\n        MOV     @R0,TL0\n        INC     R0\n        RETI\n        ORG     0030H\nMAIN:   MOV     R0,#40H\n        MOV     30H,#0\n        MOV     TMOD,#02H\n        MOV     TH0,#0D8H\n        MOV     TL0,#0D8H\n        SETB    IT0\n        MOV     IE,#83H                 ; cùng mức ưu tiên thấp\n        SETB    TR0\n        MOV     R6,#100\n        DJNZ    R6,$\n        CLR     TR0\n        CLR     EA\n        SJMP    $\nX0ISR:  MOV     31H,#45                 ; công việc: 45 × 2 chu kỳ\n        DJNZ    31H,$\n        INC     30H\n        RETI\n        END\n","note":"ISR INT0 dài 99 chu kỳ. TF0 bật ở 55 rồi giữ mức 1 qua hai lần tràn 95, 135 (phần Thời gian): chỉ 6 lần vào ISR tick cho 8 lần tràn (55…335) → mất 2 tick. Ô 40H = EDH “trông như” trễ 20 chu kỳ vì TL0 đã nạp lại.","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Ví dụ: Tick ưu tiên cao lồng vào ISR dài","code":"; Ví dụ 5: sửa bằng ưu tiên — tick mức cao lồng vào ISR dài\n; Như ví dụ 4, thêm SETB PT0: Timer 0 ở mức cao, ngắt chen\n; được vào giữa ISR INT0. Không mất tick, độ trễ tick nhỏ.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H\n        LJMP    X0ISR\n        ORG     000BH\n        MOV     @R0,TL0                 ; không đổi A, PSW: lồng an toàn\n        INC     R0\n        RETI\n        ORG     0030H\nMAIN:   MOV     R0,#40H\n        MOV     30H,#0\n        MOV     TMOD,#02H\n        MOV     TH0,#0D8H\n        MOV     TL0,#0D8H\n        SETB    IT0\n        SETB    PT0                     ; Timer 0: ưu tiên cao\n        MOV     IE,#83H\n        SETB    TR0\n        MOV     R6,#100\n        DJNZ    R6,$\n        CLR     TR0\n        CLR     EA\n        SJMP    $\nX0ISR:  MOV     31H,#45\n        DJNZ    31H,$\n        INC     30H\n        RETI\n        END\n","note":"Thêm SETB PT0: tick ở mức cao chen vào giữa ISR INT0 (gọi ở 57, ngay khi LJMP của ISR INT0 xong). 8 lần tràn, 8 lần vào ISR tick (R0 = 48H), mọi mẫu 3–4 chu kỳ. ISR INT0 dài thêm 3 × 7 chu kỳ: đó là giá phải trả.","dev":{"led":true,"btn":true},"fosc":12000000}];
const sim32=makeSim51(document.getElementById("m51-l32"),{id:"s32",presets:PR32,ram:256});
makeEx51(document.getElementById("ex-l32"),"l32",[{"t":"Thay hỏi vòng bằng ngắt INT0","d":"<p>Phần “nguồn xung” (giữ nguyên) giả lập một cảm biến nối <code>P3.2<\/code> (INT0): có <code>[30H]<\/code> chùm (0–12), mỗi chùm là <b>hai<\/b> xung xuống cách nhau 2 chu kỳ, giữa các chùm main làm việc khác 40 chu kỳ. Code mẫu hỏi vòng cờ <code>IE0<\/code> một lần sau mỗi chùm nên chỉ đếm được một nửa. Hãy sửa phần khởi tạo và bỏ đoạn hỏi vòng, dùng ngắt INT0 kích sườn để <code>31H<\/code> = số xung thật.<\/p><p>Ví dụ: <code>30H = 3<\/code> → <code>31H = 06H<\/code> (code mẫu cho <code>03H<\/code>).<\/p>","start":"; Bài 1: đếm mọi xung ở INT0 (P3.2) — thay hỏi vòng bằng ngắt\n; Phần \"nguồn xung\" giả lập cảm biến: mỗi chùm có 2 xung\n; xuống liền nhau; có [30H] chùm. Kết quả: 31H = số xung.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0030H\nMAIN:   MOV     31H,#0                  ; số xung đếm được\n; ---- sửa phần khởi tạo ----\n        SETB    IT0                     ; INT0 kích sườn\n; ---- nguồn xung: giữ nguyên ----\n        MOV     R7,30H                  ; số chùm (0-12)\n        CJNE    R7,#0,CHUM\n        SJMP    HET\nCHUM:   CLR     P3.2                    ; xung 1\n        NOP\n        SETB    P3.2\n        NOP\n        CLR     P3.2                    ; xung 2\n        NOP\n        SETB    P3.2\n; ---- sửa: hỏi vòng cờ IE0 sau mỗi chùm ----\n        JBC     IE0,CO\n        SJMP    TIEP\nCO:     INC     31H\nTIEP:                                   ; ---- giữ nguyên ----\n        MOV     R6,#20                  ; công việc khác: 40 chu kỳ\n        DJNZ    R6,$\n        DJNZ    R7,CHUM\nHET:    CLR     EA\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3}},"expect":{"iram":{"0x31":6}}},{"setup":{"iram":{"0x30":0}},"expect":{"iram":{"0x31":0}}},{"setup":{"iram":{"0x30":1}},"expect":{"iram":{"0x31":2}}},{"setup":{"iram":{"0x30":12}},"expect":{"iram":{"0x31":24}}},{"setup":{"iram":{"0x30":5}},"expect":{"iram":{"0x31":10}}},{"setup":{"iram":{"0x30":8}},"expect":{"iram":{"0x31":16}}}]},"hints":["Chạy code mẫu từng bước qua một chùm: sườn xuống thứ nhất bật IE0, sườn thứ hai rơi vào lúc IE0 đã bằng 1 nên không để lại dấu vết gì. Cờ là một bit.","Ngắt được phục vụ ngay sau lệnh đang chạy, nên ISR xóa IE0 (phần cứng xóa khi vào ngắt) trước khi xung thứ hai tới.","Phần hỏi vòng bỏ được hết; ISR chỉ cần đếm. Nhớ bật cả bit cho phép riêng của INT0 và bit cho phép chung."],"why":"Hỏi vòng chỉ thấy sự kiện vào lúc main kịp xét; nếu hai sự kiện tới trước lần xét kế tiếp thì cờ (một bit) chỉ nhớ một. Ngắt rút ngắn khoảng chờ xuống vài chu kỳ máy, nên mỗi sườn được phục vụ trước khi sườn sau tới. Nếu xung còn dày hơn độ trễ đáp ứng cộng thời gian ISR thì ngắt cũng mất: khi đó phải đếm bằng phần cứng (Timer ở chế độ counter, Bài 27)."},{"t":"Đánh giá vết độ trễ: lớn nhất, nhỏ nhất, độ rung, lỡ hạn","d":"<p>Bộ đệm bắt đầu ở <code>40H<\/code> chứa N = <code>[3FH]<\/code> mẫu độ trễ ngắt (1–16 mẫu, mỗi mẫu 1 byte, đơn vị chu kỳ máy) do ISR ghi (cách đo ở mục 32.2). Hạn chót ở <code>[3EH]<\/code>. Hãy tính <code>30H<\/code> = mẫu lớn nhất, <code>31H<\/code> = mẫu nhỏ nhất, <code>32H<\/code> = độ rung = lớn nhất − nhỏ nhất, <code>33H<\/code> = số mẫu <b>lớn hơn<\/b> hạn chót. Với 16 mẫu chương trình chạy không quá <b>340 chu kỳ máy<\/b> (gợi ý: một lần duyệt).<\/p><p>Ví dụ: mẫu <code>4 3 5 3 3 4<\/code>, hạn 4 → <code>30H = 05H<\/code>, <code>31H = 03H<\/code>, <code>32H = 02H<\/code>, <code>33H = 01H<\/code>.<\/p>","start":"; Bài 2: đánh giá vết (trace) độ trễ ngắt\n; Bộ đệm 40H.. có N = [3FH] mẫu độ trễ (chu kỳ máy, 1-16\n; mẫu) do ISR ghi. Hạn chót [3EH]. Cần: 30H = lớn nhất,\n; 31H = nhỏ nhất, 32H = độ rung = lớn nhất − nhỏ nhất,\n; 33H = số mẫu LỚN HƠN hạn chót (lỡ hạn).\n        ORG     0000H\nMAIN:   MOV     R0,#40H\n        MOV     R7,3FH\n        MOV     30H,#0                  ; lớn nhất (code mẫu chỉ tính ô này)\nLAP:    MOV     A,@R0\n        CJNE    A,30H,K1                ; C = 1 nếu A < 30H\nK1:     JC      K2\n        MOV     30H,A\nK2:     INC     R0\n        DJNZ    R7,LAP\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x3E":4,"0x3F":6,"0x40":4,"0x41":3,"0x42":5,"0x43":3,"0x44":3,"0x45":4}},"expect":{"iram":{"0x30":5,"0x31":3,"0x32":2,"0x33":1}}},{"setup":{"iram":{"0x3E":10,"0x3F":1,"0x40":7}},"expect":{"iram":{"0x30":7,"0x31":7,"0x32":0,"0x33":0}}},{"setup":{"iram":{"0x3E":9,"0x3F":6,"0x40":34,"0x41":3,"0x42":4,"0x43":3,"0x44":4,"0x45":3}},"expect":{"iram":{"0x30":34,"0x31":3,"0x32":31,"0x33":1}}},{"setup":{"iram":{"0x3E":8,"0x3F":16,"0x40":9,"0x41":9,"0x42":9,"0x43":9,"0x44":9,"0x45":9,"0x46":9,"0x47":9,"0x48":9,"0x49":9,"0x4A":9,"0x4B":9,"0x4C":9,"0x4D":9,"0x4E":9,"0x4F":9}},"expect":{"iram":{"0x30":9,"0x31":9,"0x32":0,"0x33":16}}},{"setup":{"iram":{"0x3E":128,"0x3F":8,"0x40":0,"0x41":255,"0x42":128,"0x43":1,"0x44":254,"0x45":3,"0x46":200,"0x47":5}},"expect":{"iram":{"0x30":255,"0x31":0,"0x32":255,"0x33":3}}},{"setup":{"iram":{"0x3E":9,"0x3F":16,"0x40":12,"0x41":3,"0x42":3,"0x43":40,"0x44":3,"0x45":4,"0x46":3,"0x47":3,"0x48":5,"0x49":3,"0x4A":3,"0x4B":4,"0x4C":3,"0x4D":22,"0x4E":3,"0x4F":4}},"expect":{"iram":{"0x30":40,"0x31":3,"0x32":37,"0x33":3}}}],"maxCyc":340},"hints":["Code mẫu đã tìm lớn nhất bằng CJNE A,30H,… (C = 1 khi A nhỏ hơn). Làm tương tự cho nhỏ nhất, khởi tạo 31H = FFH.","Mẫu bằng hạn chót KHÔNG lỡ hạn. Tính hạn − mẫu bằng SUBB (sau CLR C): có mượn (C = 1) đúng khi mẫu lớn hơn hạn.","Gộp cả ba việc trong cùng một vòng; tính 32H một lần sau vòng. Ba vòng riêng sẽ vượt 340 chu kỳ với 16 mẫu."],"why":"Một vết (trace) độ trễ chỉ có ích khi rút ra được các con số để so với yêu cầu: độ trễ lớn nhất (trường hợp xấu nhất), độ rung (lớn nhất − nhỏ nhất) và số lần lỡ hạn. Trường hợp xấu nhất mới quyết định hệ có đạt yêu cầu thời gian hay không; giá trị trung bình thì không. Duyệt một lần giữ chi phí tỉ lệ với số mẫu."},{"t":"Hai nguồn sự kiện: không được mất tick","d":"<p>Timer 0 tạo tick mỗi 50 chu kỳ (ISR đếm <code>30H<\/code>). Timer 1 báo một “gói dữ liệu” mỗi 200 chu kỳ; xử lý một gói là <code>[34H]<\/code> vòng (1–24) cộng 3 vào <code>35H<\/code>. Sau 4 gói, phần cuối của main (giữ nguyên) dừng hai timer cùng lúc và tự tính <code>33H<\/code> = số tick bị mất. Code mẫu để hai ngắt cùng mức và xử lý gói ngay trong ISR: khi <code>[34H]<\/code> lớn, tick bị mất. Hãy sửa (khởi tạo, vòng chờ, các ISR) để với mọi <code>[34H]<\/code>: <code>33H = 0<\/code>, <code>31H = 4<\/code>, <code>35H<\/code> = 4 × 3 × <code>[34H]<\/code> (mod 256).<\/p><p>Ví dụ: <code>34H = 24<\/code> → <code>33H = 00H<\/code>, <code>31H = 04H<\/code>, <code>35H = 20H<\/code> (code mẫu cho <code>33H = 04H<\/code>).<\/p>","start":"; Bài 3: hai nguồn sự kiện — không được mất tick\n; Timer 0: tick mỗi 50 chu kỳ (ISR đếm 30H). Timer 1: một\n; \"gói dữ liệu\" mỗi 200 chu kỳ, ISR xử lý [34H] vòng (1-24)\n; vào 35H. Sau 4 gói, main dừng hai timer CÙNG LÚC và tự\n; tính 33H = số tick bị mất. Cần: 33H = 0, 31H = 4,\n; 35H = 4 × 3 × [34H] (mod 256).\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        LJMP    T0ISR\n        ORG     001BH\n        LJMP    T1ISR\n        ORG     0030H\nMAIN:   MOV     SP,#5FH\n        MOV     30H,#0                  ; số tick\n        MOV     31H,#0                  ; số gói đã nhận\n        MOV     35H,#0                  ; kết quả xử lý\n        MOV     TMOD,#22H               ; Timer 0, 1 chế độ 2\n        MOV     TH0,#0CEH               ; 256 - 50\n        MOV     TL0,#0CEH\n        MOV     TH1,#38H                ; 256 - 200\n        MOV     TL1,#38H\n; ---- sửa từ đây ----\n        MOV     IE,#8AH                 ; EA + ET1 + ET0, cùng mức\n        ORL     TCON,#50H               ; TR1 = TR0 = 1 trong một lệnh\nCHO:    MOV     A,31H                   ; chờ đủ 4 gói\n        CJNE    A,#4,CHO\n; ---- giữ nguyên tới hết main ----\n        ANL     TCON,#0AFH              ; dừng cả hai timer cùng lúc\n        NOP                             ; tick đang chờ được phục vụ\n        NOP\n        CLR     EA\n        MOV     A,TL1                   ; tick đúng = 16 + (TL1-38H)/50\n        CLR     C\n        SUBB    A,#38H\n        MOV     B,#50\n        DIV     AB\n        ADD     A,#16\n        CLR     C\n        SUBB    A,30H\n        MOV     33H,A                   ; số tick bị mất\n        SJMP    $\n; ---- ISR: được sửa ----\nT0ISR:  INC     30H\n        RETI\nT1ISR:  PUSH    ACC\n        PUSH    PSW\n        INC     31H\n        MOV     36H,34H                 ; xử lý gói: [34H] vòng\nLAM:    MOV     A,35H\n        ADD     A,#3\n        MOV     35H,A\n        DJNZ    36H,LAM\n        POP     PSW\n        POP     ACC\n        RETI\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x34":24}},"expect":{"iram":{"0x31":4,"0x33":0,"0x35":32}}},{"setup":{"iram":{"0x34":1}},"expect":{"iram":{"0x31":4,"0x33":0,"0x35":12}}},{"setup":{"iram":{"0x34":8}},"expect":{"iram":{"0x31":4,"0x33":0,"0x35":96}}},{"setup":{"iram":{"0x34":16}},"expect":{"iram":{"0x31":4,"0x33":0,"0x35":192}}},{"setup":{"iram":{"0x34":20}},"expect":{"iram":{"0x31":4,"0x33":0,"0x35":240}}},{"setup":{"iram":{"0x34":12}},"expect":{"iram":{"0x31":4,"0x33":0,"0x35":144}}},{"setup":{"iram":{"0x34":23}},"expect":{"iram":{"0x31":4,"0x33":0,"0x35":20}}}]},"hints":["Chạy code mẫu với bộ thử 1 và xem phần Thời gian: trong lúc ISR Timer 1 chạy (khoảng 137 chu kỳ), TF0 bật rồi giữ nguyên; những lần tràn sau đó không để lại gì.","Cách 1: cho Timer 0 ưu tiên cao (bit PT0 trong IP). Tick khi đó chen được vào giữa ISR gói. ISR tick chỉ có INC 30H nên lồng vào đâu cũng an toàn.","Cách 2: ISR gói chỉ tăng một bộ đếm “gói chờ”; vòng chờ của main thấy bộ đếm khác 0 thì giảm nó (DEC một lệnh: nguyên tử) và xử lý gói. Nhớ xử lý xong gói thứ 4 trước khi rời vòng chờ."],"why":"Mỗi nguồn ngắt chỉ có một bit cờ. Nếu một ISR cùng mức chạy lâu hơn chu kỳ của nguồn khác, các sự kiện của nguồn đó dồn vào một cờ và bị mất. Hai cách sửa: đưa nguồn cần đúng giờ lên mức ưu tiên cao (ISR của nó phải ngắn và không phá ngữ cảnh của ISR bị chen), hoặc giữ ISR thật ngắn và dời việc nặng ra main (ISR chỉ ghi nhận sự kiện). Cách thứ hai còn giảm độ trễ cho mọi nguồn khác."}]);

makeQuiz("quiz32","score32",[{"q": "Main hỏi vòng chân P3.2 một lần mỗi 105 chu kỳ máy. Một xung xuống dài 40 chu kỳ đến lúc main đang bận. Điều gì xảy ra?", "o": ["Xung có thể bị bỏ lỡ hoàn toàn nếu nằm trọn giữa hai lần xét", "Xung luôn được thấy vì chân giữ mức 0 tới lần xét sau", "Xung được thấy nhưng đếm thành 2 lần", "Phần cứng tự gọi ISR INT0 dù không bật EX0"], "a": 0, "e": "Hỏi vòng chân chỉ thấy mức chân tại thời điểm xét. Xung ngắn hơn khoảng giữa hai lần xét có thể nằm trọn trong khe và mất (ví dụ 2). Hỏi vòng cờ IE0 kích sườn thì không mất lần đầu, nhưng vẫn mất nếu hai sườn tới giữa hai lần xét."}, {"q": "Timer 0 chế độ 2 với TH0 = D8H. Lệnh đầu ISR là MOV @R0,TL0 và chép được DEH. Với mô hình đọc TL0 ở chu kỳ thứ hai của lệnh, độ trễ từ lúc cờ bật tới lệnh đầu ISR là bao nhiêu?", "o": ["5 chu kỳ", "6 chu kỳ", "4 chu kỳ", "222 chu kỳ"], "a": 0, "e": "Sau lần tràn TL0 = D8H rồi tăng mỗi chu kỳ. Đọc ở chu kỳ thứ hai của lệnh đầu ISR nên độ trễ = DEH − D9H = 5 (mẫu thứ ba trong dãy đo ở mục 32.2)."}, {"q": "Hai nguồn cùng mức ưu tiên thấp. ISR của nguồn A dài 60 µs, tick của nguồn B mỗi 40 µs, ISR của B dài 7 µs. Điều nào có thể xảy ra?", "o": ["B chen vào giữa ISR của A vì chu kỳ của B ngắn hơn", "A bị mất vì B xảy ra thường xuyên hơn", "Không có gì, vì thứ tự hỏi vòng xử lý được", "Mất tick của B khi A đang được phục vụ"], "a": 3, "e": "Cùng mức thì ISR đang chạy không bị ngắt. Trong 60 µs, B có thể tràn hai lần; cờ TF chỉ một bit nên một lần mất. Thứ tự hỏi vòng chỉ quyết định ai được phục vụ trước khi nhiều cờ cùng chờ, không làm ISR dài bị ngắt."}, {"q": "Vết độ trễ của một ISR: 3, 4, 3, 34, 3, 5 chu kỳ. Yêu cầu: không quá 10 chu kỳ. Kết luận nào đúng?", "o": ["Đạt vì trung bình nhỏ hơn 10", "Không đạt: trường hợp xấu nhất 34 vượt yêu cầu dù trung bình chỉ khoảng 9", "Đạt vì 5/6 mẫu nhỏ hơn 10", "Không kết luận được vì độ rung là 31"], "a": 1, "e": "Yêu cầu thời gian so với giá trị lớn nhất (trường hợp xấu nhất), không phải trung bình. Độ rung 31 là thông tin bổ sung; con số 34 vượt yêu cầu là đủ để không đạt (ví dụ 3, bài tập 2)."}, {"q": "Cách nào KHÔNG giúp tránh mất tick khi một ISR khác cùng mức chạy quá lâu?", "o": ["Cho nguồn tick ưu tiên cao (PT0 = 1)", "Rút ngắn ISR dài, dời việc nặng ra main", "Đổi thứ tự lệnh trong ISR tick", "Đếm sự kiện bằng phần cứng (timer chế độ counter) khi chỉ cần số lượng"], "a": 2, "e": "Mất tick xảy ra vì cờ không được phục vụ kịp trong lúc ISR khác chặn. Sửa bên trong ISR tick không đổi được việc nó bị chặn; phải bỏ chặn (ưu tiên cao), giảm thời gian chặn (ISR ngắn) hoặc không cần phục vụ từng sự kiện (đếm phần cứng)."}]);

